    s = sys.stdin.read().split()[0]
    seen = set()
    rep = set()
    for i in range(len(s) - 9):
        w = s[i:i + 10]
        if w in seen:
            rep.add(w)
        else:
            seen.add(w)
    res = sorted(rep)
    print(len(res))
    if res:
        print('\n'.join(res))

