import sys

s = sys.stdin.read().split()[0]
n = len(s)
res = set()
for i in range(n - 9):
    for j in range(i + 1, n - 9):
        if s[i:i + 10] == s[j:j + 10]:
            res.add(s[i:i + 10])
res = sorted(res)
print(len(res))
if res:
    print('\n'.join(res))

